+++ b/graveyard/shims/repeat-string.cjs
@@ -0,0 +1,8 @@
+'use strict';
+// Graveyard Shift replacement for the abandoned "repeat-string" package.
+// String.prototype.repeat throws on negative counts; the original returns "", so this guards it.
+// Behaviour proven equal to the original with property-based tests; see graveyard/proofs/.
+module.exports = function repeat(str, num) {
+  if (typeof str !== 'string') throw new TypeError('expected a string');
+  return num > 0 ? str.repeat(num) : '';
+};
